function playfulFeedback(){const c=state.cats.find(c=>draft.catIds.includes(c.id))||state.cats[0];return `<section class="playful-feedback"><div class="feedback-header"><div class="feedback-pet" id="feedback-pet">${catSVG(c)}</div><div><h3>What was happening?</h3><p>A little more of their story, from you.</p></div></div><div class="context-grid" role="group" aria-label="What was happening"><span class="sr-only">Choose the real-life situation you observed, not an AI prediction.</span>${Object.entries(CONTEXTS).map(([v,info])=>`<button class="context-choice ${draft.contextTouched&&draft.confirmed===v?'active':''}" data-action="draft-context" data-value="${v}" aria-pressed="${draft.contextTouched&&draft.confirmed===v}"><span class="context-emoji" aria-hidden="true">${info.emoji}</span><span>${info.label}</span></button>`).join('')}</div><p class="feedback-status" id="feedback-status" role="status">${draft.contextTouched?(draft.confirmed==='unknown'?"That's okay. You can leave a note about what was happening.":'Got it. A little more of the story, kept.'):'Tap a little symbol, or leave it unknown.'}</p><div class="analysis-status">${icon('wave')}<span>Your observation stays separate from local model analysis.</span></div></section>`}

